SELECT COUNT(DISTINCT Patient.ID)
FROM Laboratory
JOIN Patient ON Laboratory.ID = Patient.ID
WHERE Laboratory.TG >= 200
  AND Patient.Birthday IS NOT NULL
  AND (
    (CAST(strftime('%Y', Laboratory.Date) AS INTEGER) - CAST(strftime('%Y', Patient.Birthday) AS INTEGER)
     - (strftime('%m-%d', Laboratory.Date) < strftime('%m-%d', Patient.Birthday))
    ) > 50
  );

SELECT
  (SELECT COUNT(*) FROM trans WHERE account_id = 3 AND k_symbol = 'SLUZBY' AND type IN ('VYDAJ','VYBER')) AS requests,
  (SELECT k_symbol FROM (SELECT k_symbol, SUM(amount) AS total FROM trans WHERE type IN ('VYDAJ','VYBER') GROUP BY k_symbol) WHERE total = 3539) AS aim;
